# owner: platform
"""Lay students out in seat rows, last name first."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

# ---
def seating_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One line per seat row, sorted by last name."""
    roster = list(students)
    check_seating(roster, seats_per_row)
    ordered = sorted(roster, key=name_order)
    return format_rows(ordered, seats_per_row)

# ---
def check_seating(
    roster: List[Student], seats_per_row: int
) -> None:
    """Refuse a seat count below one or an empty roster."""
    if seats_per_row <= 0:
        raise ValueError(f"bad seat count: {seats_per_row}")
    if not roster:
        raise ValueError("no students to seat")

# ---
def name_order(student: Student) -> Tuple[str, str]:
    """Sort key: last name, then first, ignoring case."""
    last = student.last_name.casefold()
    first = student.first_name.casefold()
    return (last, first)

# ---
def format_rows(
    ordered: List[Student], seats_per_row: int
) -> List[str]:
    rows = []
    for start in range(0, len(ordered), seats_per_row):
        seats = ordered[start:start + seats_per_row]
        rows.append(format_row(len(rows) + 1, seats))
    return rows

# ---
def format_row(number: int, seats: List[Student]) -> str:
    """Text for one seat row."""
    names = [student.display_name for student in seats]
    return f"Row {number}: " + " | ".join(names)
